      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉકેલ/જવાબ:</strong> નેશનલ પાર્કમાં શિકાર કરવા પર અને જંગલોને નુકસાન પહોંચાડવા પર સખત પ્રતિબંધ હોય છે.</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: નેશનલ પાર્ક = નો હન્ટિંગ ઝોન.</p></div>"
